{"title":"Journey health index, every 2 minutes","type":"vega","aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": {
      "index": "bank-journey-health",
      "%context%": true,
      "%timefield%": "@timestamp",
      "body": {
        "size": 0,
        "aggs": {
          "j": {
            "terms": {
              "field": "journey.name",
              "size": 10
            },
            "aggs": {
              "t": {
                "date_histogram": {
                  "field": "@timestamp",
                  "fixed_interval": "2m"
                },
                "aggs": {
                  "n": {
                    "sum": {
                      "field": "health.attempts"
                    }
                  },
                  "done": {
                    "sum": {
                      "field": "health.completed"
                    }
                  },
                  "tech": {
                    "sum": {
                      "field": "health.tech_failures"
                    }
                  },
                  "sat": {
                    "sum": {
                      "field": "health.satisfied"
                    }
                  },
                  "tol": {
                    "sum": {
                      "field": "health.tolerating"
                    }
                  },
                  "pv": {
                    "sum": {
                      "field": "health.page_views"
                    }
                  },
                  "pvok": {
                    "sum": {
                      "field": "health.page_views_pass"
                    }
                  },
                  "slo": {
                    "max": {
                      "field": "health.slo_completion_pct"
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.j.buckets"
    }
  },
  "transform": [
    {
      "flatten": [
        "t.buckets"
      ],
      "as": [
        "b"
      ]
    },
    {
      "filter": "datum.b.n.value > 0"
    },
    {
      "calculate": "datum.b.n.value",
      "as": "n"
    },
    {
      "calculate": "min(1, (datum.b.done.value / datum.n) / (datum.b.slo.value / 100))",
      "as": "c"
    },
    {
      "calculate": "(datum.b.sat.value + datum.b.tol.value / 2) / datum.n",
      "as": "a"
    },
    {
      "calculate": "max(0, 1 - (datum.b.tech.value / datum.n) / 0.05)",
      "as": "e"
    },
    {
      "calculate": "datum.b.pv.value > 0 ? datum.b.pvok.value / datum.b.pv.value : 1",
      "as": "x"
    },
    {
      "calculate": "round(100 * (0.4 * datum.c + 0.25 * datum.a + 0.2 * datum.e + 0.15 * datum.x))",
      "as": "health"
    },
    {
      "calculate": "toDate(datum.b.key)",
      "as": "time"
    },
    {
      "calculate": "timeFormat(datum.time, '%H:%M')",
      "as": "hm"
    }
  ],
  "mark": {
    "type": "rect",
    "tooltip": true
  },
  "encoding": {
    "x": {
      "field": "hm",
      "type": "ordinal",
      "title": null,
      "sort": {
        "field": "time"
      },
      "axis": {
        "labelAngle": 0,
        "labelOverlap": true
      }
    },
    "y": {
      "field": "key",
      "type": "nominal",
      "title": null,
      "sort": {
        "op": "min",
        "field": "health"
      }
    },
    "color": {
      "field": "health",
      "type": "quantitative",
      "title": "Health",
      "scale": {
        "type": "threshold",
        "domain": [
          80,
          90
        ],
        "range": [
          "#CC5642",
          "#D6BF57",
          "#209280"
        ]
      }
    },
    "tooltip": [
      {
        "field": "key",
        "title": "Journey"
      },
      {
        "field": "hm",
        "title": "Time"
      },
      {
        "field": "health",
        "title": "Health index"
      }
    ]
  }
}"}}

{"title":"Branch volume against failure rate","type":"vega","aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": {
      "index": "logs-bank.business-*",
      "%context%": true,
      "%timefield%": "@timestamp",
      "body": {
        "size": 0,
        "aggs": {
          "inp": {
            "filter": {
              "terms": {
                "bank.channel": [
                  "branch",
                  "atm"
                ]
              }
            },
            "aggs": {
              "b": {
                "terms": {
                  "field": "bank.branch.id",
                  "size": 50
                },
                "aggs": {
                  "r": {
                    "terms": {
                      "field": "bank.region",
                      "size": 1
                    }
                  },
                  "fail": {
                    "filter": {
                      "terms": {
                        "journey.status": [
                          "failed",
                          "pending"
                        ]
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.inp.b.buckets"
    }
  },
  "transform": [
    {
      "calculate": "datum.key",
      "as": "branch"
    },
    {
      "calculate": "datum.doc_count",
      "as": "volume"
    },
    {
      "calculate": "100 * datum.fail.doc_count / datum.doc_count",
      "as": "failure_pct"
    },
    {
      "calculate": "datum.r.buckets.length ? datum.r.buckets[0].key : 'n/a'",
      "as": "region"
    }
  ],
  "mark": {
    "type": "circle",
    "opacity": 0.75,
    "tooltip": true
  },
  "encoding": {
    "x": {
      "field": "volume",
      "type": "quantitative",
      "title": "Transactions"
    },
    "y": {
      "field": "failure_pct",
      "type": "quantitative",
      "title": "Failed %"
    },
    "size": {
      "field": "volume",
      "type": "quantitative",
      "legend": null
    },
    "color": {
      "field": "region",
      "type": "nominal",
      "title": "Region"
    },
    "tooltip": [
      {
        "field": "branch"
      },
      {
        "field": "region"
      },
      {
        "field": "volume"
      },
      {
        "field": "failure_pct",
        "format": ".1f"
      }
    ]
  }
}"}}

{"title":"Query time per table (ms, box plot)","type":"vega","aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": {
      "index": "metrics-bank.platform-*",
      "%context%": true,
      "%timefield%": "@timestamp",
      "body": {
        "size": 5000,
        "_source": [
          "postgresql.table",
          "postgresql.query.time_ms"
        ]
      }
    },
    "format": {
      "property": "hits.hits"
    }
  },
  "transform": [
    {
      "filter": "datum._source.postgresql && datum._source.postgresql.query"
    },
    {
      "calculate": "datum._source.postgresql.table",
      "as": "table"
    },
    {
      "calculate": "datum._source.postgresql.query.time_ms",
      "as": "ms"
    }
  ],
  "mark": {
    "type": "boxplot",
    "extent": "min-max"
  },
  "encoding": {
    "y": {
      "field": "table",
      "type": "nominal",
      "title": null
    },
    "x": {
      "field": "ms",
      "type": "quantitative",
      "scale": {
        "type": "symlog"
      },
      "title": "Query time ms (log scale)"
    },
    "color": {
      "field": "table",
      "type": "nominal",
      "legend": null
    }
  }
}"}}

{"title":"True cause against the agent's first answer","type":"vega","aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": {
      "index": "bank-ai-scores",
      "%context%": true,
      "%timefield%": "@timestamp",
      "body": {
        "size": 0,
        "aggs": {
          "t": {
            "terms": {
              "field": "cause.true",
              "size": 12
            },
            "aggs": {
              "a": {
                "terms": {
                  "field": "cause.top1",
                  "size": 12
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.t.buckets"
    }
  },
  "transform": [
    {
      "flatten": [
        "a.buckets"
      ],
      "as": [
        "ans"
      ]
    },
    {
      "calculate": "replace(datum.key, 'CAUSE: ', '')",
      "as": "truth"
    },
    {
      "calculate": "replace(datum.ans.key, 'CAUSE: ', '')",
      "as": "answer"
    },
    {
      "calculate": "datum.ans.doc_count",
      "as": "runs"
    },
    {
      "calculate": "datum.truth == datum.answer ? 'correct' : 'miss'",
      "as": "result"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "rect",
        "tooltip": true
      },
      "encoding": {
        "x": {
          "field": "answer",
          "type": "nominal",
          "title": "First answer",
          "axis": {
            "labelAngle": -30,
            "labelLimit": 220
          }
        },
        "y": {
          "field": "truth",
          "type": "nominal",
          "title": "True cause",
          "axis": {
            "labelLimit": 260
          }
        },
        "color": {
          "field": "result",
          "type": "nominal",
          "scale": {
            "domain": [
              "correct",
              "miss"
            ],
            "range": [
              "#209280",
              "#CC5642"
            ]
          },
          "title": null
        },
        "opacity": {
          "field": "runs",
          "type": "quantitative",
          "legend": null,
          "scale": {
            "range": [
              0.35,
              1
            ]
          }
        },
        "tooltip": [
          {
            "field": "truth"
          },
          {
            "field": "answer"
          },
          {
            "field": "runs"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "color": "white"
      },
      "encoding": {
        "x": {
          "field": "answer",
          "type": "nominal"
        },
        "y": {
          "field": "truth",
          "type": "nominal"
        },
        "text": {
          "field": "runs"
        }
      }
    }
  ]
}"}}

